	    public void EncodeBase64NVARCHARFields(TenantPM entityPM)
        {
            if (String.IsNullOrWhiteSpace(entityPM.EncodeBase64NVARCHARFieldsBy)) 
            {
                return;
            }
            if (!String.IsNullOrWhiteSpace(entityPM.InvoiceSection1)) //T4 find type == nText 
            {
                entityPM.InvoiceSection1 = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.InvoiceSection1));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.InvoiceSection2)) //T4 find type == nText 
            {
                entityPM.InvoiceSection2 = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.InvoiceSection2));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.BankDetails)) //T4 find type == nText 
            {
                entityPM.BankDetails = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.BankDetails));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.SearchFields)) //T4 find type == nText 
            {
                entityPM.SearchFields = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.SearchFields));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.LayoutDirection)) //T4 find type == nText 
            {
                entityPM.LayoutDirection = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.LayoutDirection));
            }
            entityPM.EncodeBase64NVARCHARFieldsBy=null;
		}
